from __future__ import annotations

import base64
import binascii
import importlib.util
import json
import logging
import sys
import xml.etree.ElementTree as ET
from dataclasses import dataclass
from pathlib import Path
from types import MappingProxyType
from typing import Any, Mapping, Protocol

from fastapi import Body, Depends, FastAPI, HTTPException, Request, status

try:  # pragma: no cover - optional repository seam
    from backend.shared import contracts as shared_contracts  # type: ignore
except Exception:  # pragma: no cover - isolated kit execution fallback
    shared_contracts = None

try:  # pragma: no cover - package import path when promoted
    from .observability import (
        StructuredAuthLogger,
        ensure_request_id,
        redact_secret,
    )
except Exception:  # pragma: no cover - direct file execution fallback
    _OBS_PATH = Path(__file__).with_name("observability.py")
    _OBS_SPEC = importlib.util.spec_from_file_location(
        "req002_auth_observability",
        _OBS_PATH,
    )
    if _OBS_SPEC is None or _OBS_SPEC.loader is None:  # pragma: no cover - defensive
        raise ImportError("Could not load REQ-002 observability helper.")
    _OBS_MODULE = importlib.util.module_from_spec(_OBS_SPEC)
    sys.modules.setdefault(_OBS_SPEC.name, _OBS_MODULE)
    _OBS_SPEC.loader.exec_module(_OBS_MODULE)
    StructuredAuthLogger = _OBS_MODULE.StructuredAuthLogger
    ensure_request_id = _OBS_MODULE.ensure_request_id
    redact_secret = _OBS_MODULE.redact_secret

LOGGER = logging.getLogger(__name__)

PermissionSource = (
    Mapping[str, set[str] | frozenset[str] | list[str] | tuple[str, ...]] | None
)

DEFAULT_PERMISSION_MAP = MappingProxyType(
    {
        "slice1-reader": frozenset({"documents:read"}),
        "slice1-validator": frozenset({"documents:read", "tasks:validate"}),
        "slice1-admin": frozenset(
            {"documents:read", "documents:write", "tasks:validate"}
        ),
    }
)

MSFT_ROLE_CLAIM = "http://schemas.microsoft.com/ws/2008/06/identity/claims/role"
NAME_ID_CLAIM = "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier"


class AuthenticationError(ValueError):
    """Raised when a caller cannot be authenticated into a stable actor context."""


@dataclass(frozen=True)
class ActorContext:
    id: str
    subject: str
    username: str
    display_name: str
    active: bool
    identity_provider: str | None
    claims_source: str
    permission_refs: tuple[str, ...]
    permissions: tuple[str, ...]
    claims_fingerprint: str

    @property
    def actor_id(self) -> str:
        return self.id

    def as_dict(self) -> dict[str, Any]:
        payload = {
            "id": self.id,
            "display_name": self.display_name,
            "active": self.active,
            "permissions": list(self.permissions),
            "username": self.username,
            "subject": self.subject,
            "identity_provider": self.identity_provider,
            "claims_source": self.claims_source,
            "permission_refs": list(self.permission_refs),
        }
        if shared_contracts and hasattr(shared_contracts, "actor_context_to_dict"):
            converter = getattr(shared_contracts, "actor_context_to_dict")
            try:
                return converter(payload)  # pragma: no cover - repo seam only
            except Exception:
                return payload
        return payload


class WriteSink(Protocol):
    def write(self, *, actor: ActorContext, payload: Mapping[str, Any]) -> Mapping[str, Any]:
        ...


class AuditSink(Protocol):
    def record(
        self,
        *,
        actor: ActorContext,
        action: str,
        payload: Mapping[str, Any],
    ) -> None:
        ...


class NullWriteSink:
    def write(self, *, actor: ActorContext, payload: Mapping[str, Any]) -> Mapping[str, Any]:
        return {"accepted": True, "actor_id": actor.id, "payload": dict(payload)}


class NullAuditSink:
    def record(
        self,
        *,
        actor: ActorContext,
        action: str,
        payload: Mapping[str, Any],
    ) -> None:
        return None


def normalize_permission_map(permission_map: PermissionSource) -> Mapping[str, frozenset[str]]:
    source = permission_map or DEFAULT_PERMISSION_MAP
    normalized: dict[str, frozenset[str]] = {}
    for ref, permissions in source.items():
        normalized[str(ref)] = frozenset(sorted(str(permission) for permission in permissions))
    return MappingProxyType(normalized)


def _urlsafe_b64decode(raw: str) -> bytes:
    padding = "=" * (-len(raw) % 4)
    return base64.urlsafe_b64decode((raw + padding).encode("utf-8"))


def _json_load_mapping(raw: str) -> Mapping[str, Any]:
    value = json.loads(raw)
    if not isinstance(value, Mapping):
        raise AuthenticationError("Claims payload must decode to an object.")
    return value


def _first_non_empty(claims: Mapping[str, Any], *keys: str) -> str | None:
    for key in keys:
        value = claims.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return None


def _to_strings(value: Any) -> tuple[str, ...]:
    if value is None:
        return ()
    if isinstance(value, str):
        return (value,) if value.strip() else ()
    if isinstance(value, Mapping):
        return ()
    if isinstance(value, (list, tuple, set, frozenset)):
        values = [str(item).strip() for item in value if str(item).strip()]
        return tuple(values)
    return (str(value).strip(),) if str(value).strip() else ()


def _claims_fingerprint(claims: Mapping[str, Any]) -> str:
    canonical = json.dumps(claims, sort_keys=True, default=str)
    encoded = base64.urlsafe_b64encode(canonical.encode("utf-8")).decode("utf-8")
    return encoded[:24]


def _collect_permission_refs(claims: Mapping[str, Any]) -> tuple[str, ...]:
    refs: set[str] = set()

    for key in (
        "groups",
        "roles",
        "role",
        "memberOf",
        "member_of",
        "idp_group_refs",
        MSFT_ROLE_CLAIM,
    ):
        refs.update(_to_strings(claims.get(key)))

    realm_access = claims.get("realm_access")
    if isinstance(realm_access, Mapping):
        refs.update(_to_strings(realm_access.get("roles")))

    return tuple(sorted(ref for ref in refs if ref))


def _parse_active_flag(value: Any) -> bool | None:
    if isinstance(value, bool):
        return value
    if isinstance(value, int) and value in (0, 1):
        return bool(value)
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"true", "1", "yes", "y", "enabled", "active"}:
            return True
        if normalized in {"false", "0", "no", "n", "disabled", "inactive"}:
            return False
    return None


def _resolve_active_flag(claims: Mapping[str, Any]) -> bool:
    account_status = claims.get("account_status")
    parsed_status = _parse_active_flag(account_status)
    if parsed_status is not None:
        return parsed_status

    for key in ("active", "is_active", "enabled", "account_enabled"):
        parsed = _parse_active_flag(claims.get(key))
        if parsed is not None:
            return parsed

    return True


def normalize_actor_context(
    claims: Mapping[str, Any],
    *,
    claims_source: str,
    permission_map: Mapping[str, frozenset[str]] | None = None,
) -> ActorContext:
    permissions_by_ref = normalize_permission_map(permission_map)

    subject = _first_non_empty(
        claims,
        "sub",
        "nameid",
        "name_id",
        NAME_ID_CLAIM,
    )
    if not subject:
        raise AuthenticationError("Authenticated identity is missing subject or NameID.")

    identity_provider = _first_non_empty(
        claims,
        "iss",
        "issuer",
        "identity_provider",
    )
    actor_id = f"{identity_provider}:{subject}" if identity_provider else subject

    username = _first_non_empty(
        claims,
        "preferred_username",
        "upn",
        "email",
        "name",
        "username",
        "nameid",
        NAME_ID_CLAIM,
        "sub",
    )
    if not username:
        raise AuthenticationError("Authenticated identity is missing a usable username.")

    display_name = _first_non_empty(
        claims,
        "name",
        "display_name",
        "full_name",
        "email",
        "preferred_username",
        "username",
    ) or username

    permission_refs = _collect_permission_refs(claims)
    permissions: set[str] = set()
    for ref in permission_refs:
        permissions.update(permissions_by_ref.get(ref, frozenset()))

    return ActorContext(
        id=actor_id,
        subject=subject,
        username=username,
        display_name=display_name,
        active=_resolve_active_flag(claims),
        identity_provider=identity_provider,
        claims_source=claims_source,
        permission_refs=permission_refs,
        permissions=tuple(sorted(permissions)),
        claims_fingerprint=_claims_fingerprint(claims),
    )


def parse_oidc_bearer_token(token: str) -> Mapping[str, Any]:
    stripped = token.strip()
    if not stripped:
        raise AuthenticationError("Bearer token is empty.")

    try:
        if stripped.startswith("{"):
            return _json_load_mapping(stripped)

        if stripped.count(".") >= 1:
            segments = stripped.split(".")
            payload_segment = segments[1] if len(segments) > 1 else segments[0]
            return _json_load_mapping(_urlsafe_b64decode(payload_segment).decode("utf-8"))

        return _json_load_mapping(_urlsafe_b64decode(stripped).decode("utf-8"))
    except (AuthenticationError, json.JSONDecodeError, UnicodeDecodeError, binascii.Error) as exc:
        raise AuthenticationError("Bearer token could not be decoded into claims.") from exc


def _local_name(tag: str) -> str:
    return tag.rsplit("}", 1)[-1]


def _decode_possible_base64_xml(assertion: str) -> str:
    stripped = assertion.strip()
    if not stripped:
        raise AuthenticationError("SAML assertion is empty.")

    if stripped.startswith("<"):
        return stripped

    try:
        decoded = base64.b64decode(stripped, validate=True).decode("utf-8")
        return decoded
    except (binascii.Error, UnicodeDecodeError) as exc:
        raise AuthenticationError("SAML assertion could not be decoded.") from exc


def parse_saml_assertion(assertion: str) -> Mapping[str, Any]:
    xml_text = _decode_possible_base64_xml(assertion)

    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise AuthenticationError("SAML assertion XML could not be parsed.") from exc

    claims: dict[str, Any] = {}

    for element in root.iter():
        name = _local_name(element.tag)
        if name == "Issuer" and element.text and not claims.get("issuer"):
            claims["issuer"] = element.text.strip()
            continue

        if name == "NameID" and element.text and not claims.get("nameid"):
            value = element.text.strip()
            claims["nameid"] = value
            claims.setdefault(NAME_ID_CLAIM, value)
            continue

        if name != "Attribute":
            continue

        attr_name = (
            element.attrib.get("Name")
            or element.attrib.get("FriendlyName")
            or element.attrib.get("AttributeName")
        )
        if not attr_name:
            continue

        values = [
            child.text.strip()
            for child in element
            if _local_name(child.tag) == "AttributeValue"
            and child.text
            and child.text.strip()
        ]
        if not values:
            continue

        existing = claims.get(attr_name)
        if existing is None:
            claims[attr_name] = values if len(values) > 1 else values[0]
        else:
            merged = list(_to_strings(existing)) + values
            claims[attr_name] = merged

    return claims


def authenticate_request(
    request: Request,
    *,
    permission_map: Mapping[str, frozenset[str]],
) -> ActorContext:
    auth_header = request.headers.get("Authorization")
    saml_assertion = request.headers.get("X-SAML-Assertion")

    if auth_header and auth_header.lower().startswith("bearer "):
        claims = parse_oidc_bearer_token(auth_header.split(" ", 1)[1])
        return normalize_actor_context(
            claims,
            claims_source="oidc",
            permission_map=permission_map,
        )

    if saml_assertion:
        claims = parse_saml_assertion(saml_assertion)
        return normalize_actor_context(
            claims,
            claims_source="saml",
            permission_map=permission_map,
        )

    raise AuthenticationError("Anonymous caller has no authentication material.")


def _auth_material_metadata(request: Request) -> tuple[str, str]:
    auth_header = request.headers.get("Authorization")
    saml_assertion = request.headers.get("X-SAML-Assertion")

    if auth_header and auth_header.lower().startswith("bearer "):
        raw = auth_header.split(" ", 1)[1]
        return "bearer", redact_secret(raw)

    if saml_assertion:
        return "saml", redact_secret(saml_assertion)

    return "none", "<redacted>"


def _http_401() -> HTTPException:
    return HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail={"error": "authentication_required"},
        headers={"WWW-Authenticate": "Bearer"},
    )


def _http_403() -> HTTPException:
    return HTTPException(
        status_code=status.HTTP_403_FORBIDDEN,
        detail={"error": "forbidden"},
    )


def get_request_actor(request: Request) -> ActorContext:
    cached = getattr(request.state, "actor_context", None)
    if isinstance(cached, ActorContext):
        return cached

    permission_map = request.app.state.auth_permission_map
    auth_logger: StructuredAuthLogger = request.app.state.auth_logger
    try:
        actor = authenticate_request(request, permission_map=permission_map)
    except AuthenticationError as exc:
        material_type, material_preview = _auth_material_metadata(request)
        auth_logger.emit(
            logging.INFO,
            "auth.authentication_failed",
            request=request,
            status_code=status.HTTP_401_UNAUTHORIZED,
            reason="authentication_required",
            auth_material_type=material_type,
            auth_material_preview=material_preview,
            error_class=exc.__class__.__name__,
        )
        raise _http_401() from exc

    request.state.actor_context = actor
    return actor


def require_permissions(*required_permissions: str):
    required = tuple(sorted({permission for permission in required_permissions if permission}))

    def dependency(request: Request) -> ActorContext:
        actor = get_request_actor(request)
        auth_logger: StructuredAuthLogger = request.app.state.auth_logger

        if not actor.active:
            auth_logger.emit(
                logging.INFO,
                "auth.authorization_denied",
                request=request,
                actor_id=actor.id,
                status_code=status.HTTP_403_FORBIDDEN,
                reason="inactive_actor",
            )
            raise _http_403()

        missing = [permission for permission in required if permission not in actor.permissions]
        if missing:
            auth_logger.emit(
                logging.INFO,
                "auth.authorization_denied",
                request=request,
                actor_id=actor.id,
                status_code=status.HTTP_403_FORBIDDEN,
                reason="missing_permission",
                required_permissions_count=len(required),
                missing_permissions_count=len(missing),
            )
            raise _http_403()
        return actor

    return dependency


def create_app(
    *,
    permission_map: PermissionSource = None,
    writer: WriteSink | None = None,
    auditor: AuditSink | None = None,
) -> FastAPI:
    app = FastAPI(title="Slice-1 auth session and RBAC policy")
    app.state.auth_permission_map = normalize_permission_map(permission_map)
    app.state.write_sink = writer or NullWriteSink()
    app.state.audit_sink = auditor or NullAuditSink()
    app.state.auth_logger = StructuredAuthLogger(LOGGER)

    @app.middleware("http")
    async def attach_request_correlation(request: Request, call_next):
        request_id = ensure_request_id(request)
        response = await call_next(request)
        response.headers["X-Request-Id"] = request_id
        return response

    @app.get("/auth/me")
    def get_auth_me(actor: ActorContext = Depends(get_request_actor)) -> dict[str, Any]:
        return actor.as_dict()

    @app.post("/documents/write-test")
    def write_test_document(
        payload: dict[str, Any] = Body(...),
        request: Request | None = None,
        actor: ActorContext = Depends(require_permissions("documents:write")),
    ) -> dict[str, Any]:
        if request is None:  # pragma: no cover - FastAPI always injects Request
            raise RuntimeError("Request injection is required.")

        writer_sink: WriteSink = request.app.state.write_sink
        audit_sink: AuditSink = request.app.state.audit_sink

        write_result = writer_sink.write(actor=actor, payload=payload)
        audit_sink.record(
            actor=actor,
            action="documents.write_test",
            payload=payload,
        )
        return {
            "status": "ok",
            "actor_id": actor.id,
            "result": dict(write_result),
        }

    return app


__all__ = [
    "ActorContext",
    "AuthenticationError",
    "DEFAULT_PERMISSION_MAP",
    "authenticate_request",
    "create_app",
    "get_request_actor",
    "normalize_actor_context",
    "normalize_permission_map",
    "parse_oidc_bearer_token",
    "parse_saml_assertion",
    "require_permissions",
]
