@pytest.fixture()
def auth_module():
    return _load_module()


def _jwt_for_claims(claims: dict[str, object]) -> str:
    header = {"alg": "none", "typ": "JWT"}

    def _segment(value: dict[str, object]) -> str:
        encoded = base64.urlsafe_b64encode(json.dumps(value).encode("utf-8")).decode("utf-8")
        return encoded.rstrip("=")

    return f"{_segment(header)}.{_segment(claims)}."


def _bearer_headers(claims: dict[str, object], **extra: str) -> dict[str, str]:
    return {"Authorization": f"Bearer {_jwt_for_claims(claims)}", **extra}


def _saml_assertion(
    *,
    issuer: str,
    nameid: str,
    attributes: dict[str, str | list[str]],
) -> str:
    attribute_blocks = []
    for name, raw_value in attributes.items():
        values = raw_value if isinstance(raw_value, list) else [raw_value]
        attribute_values = "".join(
            f"<AttributeValue>{value}</AttributeValue>" for value in values
        )
        attribute_blocks.append(f'<Attribute Name="{name}">{attribute_values}</Attribute>')

    xml = (
        "<Assertion>"
        f"<Issuer>{issuer}</Issuer>"
        "<Subject>"
        f"<NameID>{nameid}</NameID>"
        "</Subject>"
        "<AttributeStatement>"
        f"{''.join(attribute_blocks)}"
        "</AttributeStatement>"
        "</Assertion>"
    )
    return base64.b64encode(xml.encode("utf-8")).decode("utf-8")


class RecordingWriter:
    def __init__(self) -> None:
        self.calls: list[dict[str, object]] = []

    def write(self, *, actor, payload):
